const profileRows = $('Load Athlete Profile').all();
const workoutRows = $('Load Workout History').all();

const profile = {};
for (const r of profileRows) {
  const k = (r.json.setting || '').toLowerCase().replace(/\s+/g, '_');
  if (k) profile[k] = r.json.value;
}

const goal = profile.primary_goal || 'general fitness';
const trainingAge = profile.training_age || '1-2 years';
const daysPerWeek = parseInt(profile.days_per_week) || 4;
const sessionLength = parseInt(profile.session_length_minutes) || 60;
const equipment = profile.equipment || 'full gym';
const limitations = profile.injuries_limitations || 'none';
const preferredStyle = profile.preferred_style || 'mixed';
const currentLifts = profile.current_lifts || '';

// Last 4 weeks of workouts
const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 28);
const recentWorkouts = workoutRows
  .map(r => r.json)
  .filter(w => w.date && new Date(w.date) >= cutoff)
  .sort((a, b) => new Date(b.date) - new Date(a.date));

// Extract PRs and volume trends
const exerciseMap = {};
for (const w of recentWorkouts) {
  const ex = w.exercise;
  const load = parseFloat(w.weight_kg || w.weight_lbs || 0);
  const reps = parseInt(w.reps) || 0;
  if (!ex) continue;
  if (!exerciseMap[ex] || load > exerciseMap[ex].maxLoad) {
    exerciseMap[ex] = { maxLoad: load, reps, date: w.date };
  }
}

const recentPRs = Object.entries(exerciseMap)
  .map(([exercise, data]) => ({ exercise, ...data }))
  .slice(0, 8);

// Sessions per week trend
const weeksBack = [0, 1, 2, 3].map(w => {
  const start = new Date();
  start.setDate(start.getDate() - (w + 1) * 7);
  const end = new Date();
  end.setDate(end.getDate() - w * 7);
  const count = recentWorkouts.filter(wo => {
    const d = new Date(wo.date);
    return d >= start && d < end;
  }).length;
  return count;
});

const avgSessionsLast4Weeks = (weeksBack.reduce((a, b) => a + b, 0) / 4).toFixed(1);

// Notes from last week
const lastWeekNotes = recentWorkouts
  .filter(w => {
    const d = new Date(w.date);
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - 7);
    return d >= cutoffDate;
  })
  .map(w => w.notes)
  .filter(Boolean)
  .join(' | ');

return [{
  json: {
    goal, trainingAge, daysPerWeek, sessionLength,
    equipment, limitations, preferredStyle, currentLifts,
    recentPRs, avgSessionsLast4Weeks,
    weeksBack,
    lastWeekNotes,
    totalRecentWorkouts: recentWorkouts.length,
    weekOf: new Date().toISOString().split('T')[0]
  }
}];

values.content:
Design this week's training program.

Athlete profile:
- Primary goal: {{ $json.goal }}
- Training age: {{ $json.trainingAge }}
- Days available: {{ $json.daysPerWeek }} per week
- Session length: {{ $json.sessionLength }} minutes
- Equipment: {{ $json.equipment }}
- Injuries/limitations: {{ $json.limitations }}
- Preferred style: {{ $json.preferredStyle }}
- Current lifts/benchmarks: {{ $json.currentLifts || 'not provided' }}

Recent training data (last 4 weeks):
- Average sessions/week: {{ $json.avgSessionsLast4Weeks }}
- Session counts by week (most recent first): {{ $json.weeksBack.join(', ') }}
- Total logged workouts: {{ $json.totalRecentWorkouts }}
- Recent top loads by exercise: {{ $json.recentPRs.map(p => p.exercise + ': ' + p.maxLoad + ' x' + p.reps).join(', ') || 'no data yet' }}
- Notes from last week: {{ $json.lastWeekNotes || 'none' }}

Respond with this JSON structure:
{
  "week_of": "{{ $json.weekOf }}",
  "program_focus": "one sentence on what this week emphasizes and why, based on their history",
  "coach_note": "2-3 sentences — direct and honest assessment of last week and what to focus on this week. Reference their actual data.",
  "sessions": [
    {
      "day": "Monday",
      "session_type": "e.g. Lower Body Strength",
      "estimated_duration_minutes": 55,
      "warm_up": "brief warm-up description, 2-3 movements",
      "exercises": [
        {
          "name": "Back Squat",
          "sets": 4,
          "reps": "5",
          "load_guidance": "e.g. 75-80% 1RM or RPE 7-8",
          "rest_seconds": 180,
          "coaching_cue": "one specific technical cue for this athlete",
          "notes": "e.g. drop 5% from last week if knees felt off"
        }
      ],
      "cool_down": "brief cool-down or mobility work",
      "session_notes": "anything specific about pacing, focus, or how to gauge intensity today"
    }
  ],
  "weekly_targets": {
    "total_sets": "approximate total working sets this week",
    "focus_muscles": ["primary muscle groups trained this week"],
    "deload": false
  },
  "nutrition_reminder": "one practical nutrition note relevant to their goal this week — specific, not generic",
  "next_week_preview": "one sentence on what progression to expect next week if this week goes well"
}

