const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let program;
try {
  program = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
program._athleteContext = $('Build Athlete Context').first().json;
return [{ json: program }];

const p = $input.first().json;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const sessionCards = (p.sessions || []).map((s, i) => {
  const exerciseRows = (s.exercises || []).map(ex => `
    <div style="padding:10px 0;border-bottom:1px solid #f0ede8">
      <div style="display:flex;justify-content:space-between;align-items:baseline">
        <strong style="font-size:14px">${esc(ex.name)}</strong>
        <span style="font-family:monospace;font-size:13px;color:#555">${ex.sets}×${esc(ex.reps)} · ${esc(ex.load_guidance)}</span>
      </div>
      <div style="font-size:12px;color:#888;margin-top:3px">Rest: ${ex.rest_seconds}s &nbsp;|&nbsp; ${esc(ex.coaching_cue)}</div>
      ${ex.notes ? `<div style="font-size:12px;color:#b45309;margin-top:2px">↳ ${esc(ex.notes)}</div>` : ''}
    </div>`).join('');

  return `<div style="background:#fff;border:1px solid #e8e4df;border-radius:8px;margin-bottom:14px;overflow:hidden">
    <div style="background:#2d3748;color:#fff;padding:10px 16px;display:flex;justify-content:space-between;align-items:center">
      <strong style="font-size:14px">${esc(s.day)} — ${esc(s.session_type)}</strong>
      <span style="font-size:12px;color:#a0aec0">~${s.estimated_duration_minutes} min</span>
    </div>
    <div style="padding:14px 16px">
      ${s.warm_up ? `<div style="font-size:12px;color:#888;margin-bottom:10px">🔥 Warm-up: ${esc(s.warm_up)}</div>` : ''}
      ${exerciseRows}
      ${s.cool_down ? `<div style="font-size:12px;color:#888;margin-top:10px">🧊 Cool-down: ${esc(s.cool_down)}</div>` : ''}
      ${s.session_notes ? `<div style="background:#f7f5f0;border-radius:4px;padding:8px 12px;margin-top:10px;font-size:13px;color:#555">${esc(s.session_notes)}</div>` : ''}
    </div>
  </div>`;
}).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f0eb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#1a1a1a">
<div style="max-width:620px;margin:0 auto">
  <div style="background:#1a202c;color:#fff;padding:20px 24px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#718096;margin-bottom:4px">Weekly Training Program</div>
    <div style="font-size:19px;font-weight:700">${esc(p.program_focus)}</div>
    <div style="font-size:13px;color:#a0aec0;margin-top:4px">Week of ${esc(p.week_of)} · ${(p.sessions||[]).length} sessions</div>
  </div>

  <div style="background:#fff;padding:18px 24px;border-left:1px solid #eee;border-right:1px solid #eee">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:6px">Coach's Note</div>
    <p style="font-size:15px;line-height:1.7;color:#333;margin:0">${esc(p.coach_note)}</p>
  </div>

  <div style="background:#fff;padding:18px 24px;border:1px solid #eee;border-top:3px solid #f0ede8">
    ${sessionCards}
  </div>

  <div style="background:#fff;padding:16px 24px;border:1px solid #eee;border-top:3px solid #f0ede8">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;font-size:13px">
      <div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#888;margin-bottom:4px">Weekly targets</div>
        <div>~${esc(p.weekly_targets?.total_sets)} working sets</div>
        <div style="color:#555">${(p.weekly_targets?.focus_muscles||[]).join(', ')}</div>
        ${p.weekly_targets?.deload ? '<div style="color:#d97706;font-weight:600">⚡ Deload week</div>' : ''}
      </div>
      <div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#888;margin-bottom:4px">Nutrition note</div>
        <div style="color:#555;line-height:1.5">${esc(p.nutrition_reminder)}</div>
      </div>
    </div>
  </div>

  ${p.next_week_preview ? `<div style="background:#edf2ff;padding:12px 24px;border:1px solid #c5d4f8;font-size:13px;color:#3c4fa0">
    <strong>Next week:</strong> ${esc(p.next_week_preview)}
  </div>` : ''}

  <div style="background:#1a202c;color:#555;font-size:11px;padding:12px 24px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Gym Programming Coach · ${esc(p.week_of)}
  </div>
</div>
</body></html>`;

return [{ json: { html, weekOf: p.week_of, sessionCount: (p.sessions||[]).length } }];

const body = $input.first().json.body;
const required = ['exercise', 'sets', 'reps'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}
return [{
  json: {
    valid: true,
    date: body.date || new Date().toISOString().split('T')[0],
    exercise: body.exercise.trim(),
    sets: parseInt(body.sets) || 1,
    reps: parseInt(body.reps) || 0,
    weight_kg: parseFloat(body.weight_kg) || null,
    weight_lbs: parseFloat(body.weight_lbs) || null,
    rpe: parseFloat(body.rpe) || null,
    notes: (body.notes || '').slice(0, 300),
    sessionType: body.session_type || '',
    loggedAt: new Date().toISOString()
  }
}];
